import { DesignElement } from './studioTypes';

export interface StudioComponent {
  id: string;
  name: string;
  category: StudioComponentCategory;
  subcategory?: string;
  thumbnail: string; // color for preview
  elements: Partial<DesignElement>[];
  tags: string[];
}

export type StudioComponentCategory =
  | 'Buttons' | 'Cards' | 'Navigation' | 'Forms' | 'Typography'
  | 'Layout' | 'Data Display' | 'Feedback' | 'Media' | 'Wireframes'
  | 'Icons' | 'Social' | 'E-commerce' | 'Charts' | 'Templates';

