const uid = () => crypto.randomUUID();

function makeButton(name: string, w: number, h: number, fill: string, textColor: string, radius: number, text: string): StudioComponent['elements'] {
  return [
    { type: 'rectangle', x: 0, y: 0, width: w, height: h, fill, borderRadius: radius, name: `${name} bg` },
    { type: 'text', x: w * 0.15, y: h * 0.25, width: w * 0.7, height: h * 0.5, fill: textColor, text, fontSize: 14, fontWeight: '600', textAlign: 'center', name: `${name} label` },
  ];
}

function makeCard(name: string, w: number, h: number, fill: string, radius: number, extras: Partial<DesignElement>[] = []): StudioComponent['elements'] {
  return [
    { type: 'rectangle', x: 0, y: 0, width: w, height: h, fill, borderRadius: radius, shadowBlur: 12, shadowY: 4, shadowColor: 'rgba(0,0,0,0.08)', name: `${name} card` },
    ...extras,
  ];
}

